using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "AuspiciousChantingAction", menuName = "Data/Battle/Battle Actions/Sothis/AuspiciousChanting Action")]
public class AuspiciousChantingAction : ChantingAction
{
	[Header("Draw Action")]
	[SerializeField]
	private DrawAction drawAction;

	public DrawAction DrawAction => drawAction;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		drawAction.CastAmount(amount, source);
		CastTarget(target, source);
	}
}
